/**
 * Toxic-flow capability patterns: the data half of `toxic-flow-classify.ts`.
 *
 * Which paths, commands, executables, hosts and tool names contribute a
 * session capability is detection data, so it lives in
 * `threats/flow/capabilities.yaml` rather than in code. Connectors ship that file
 * in their bundled threats directory and the evaluator reads it from there
 * ({@link loadFlowCapabilities}). The core also embeds a byte-for-byte copy
 * (`toxic-flow-capabilities.data.ts`, regenerated by
 * `scripts/embed-flow-capabilities.mjs` and drift-tested) that the pure
 * classifier uses by default and that stands in when a threats directory has no
 * `flow/capabilities.yaml` (a custom rules directory, the MCP gateway's embedded
 * rule set).
 *
 * A file that exists but cannot be read or validated is rejected as a whole,
 * logged, and replaced by the embedded copy: the signal keeps running on the
 * shipped patterns rather than on half a file.
 */

import { stat } from "node:fs/promises";
import { join } from "node:path";
import { parse as parseYaml } from "yaml";
import { getFileContent } from "./file-utils.js";
import { EMBEDDED_FLOW_CAPABILITIES_YAML } from "./toxic-flow-capabilities.data.js";
import type { Logger } from "./types.js";
import { nullLogger } from "./types.js";

/** Path of the capability file relative to a threats directory. */
export const FLOW_CAPABILITIES_RELATIVE_PATH = join("flow", "capabilities.yaml");

export interface SensitivePathPattern {
	pattern: RegExp;
	label: string;
	kind: "sensitive_file" | "database_dump";
	secret: boolean;
}

interface CredentialCommandPattern {
	pattern: RegExp;
	label: string;
	kind: "credential_command" | "database_dump";
}

interface DestructiveCommandPattern {
	pattern: RegExp;
	label: string;
}

export interface FlowCapabilityPatterns {
	trustedDomains: readonly string[];
	exfilSinks: readonly string[];
	sensitivePaths: readonly SensitivePathPattern[];
	credentialCommands: readonly CredentialCommandPattern[];
	destructiveCommands: readonly DestructiveCommandPattern[];
	broadDeleteTargets: ReadonlySet<string>;
	broadDeletePatterns: readonly RegExp[];
	commandPrefixes: ReadonlySet<string>;
	executables: {
		httpClients: ReadonlySet<string>;
		rawSocketClients: ReadonlySet<string>;
		copyClients: ReadonlySet<string>;
		mailClients: ReadonlySet<string>;
		dnsClients: ReadonlySet<string>;
		interpreters: ReadonlySet<string>;
		shells: ReadonlySet<string>;
	};
	interpreterNetworkApi: RegExp;
	interpreterPayloadHint: RegExp;
	toolNames: {
		send: RegExp;
		webRead: RegExp;
		webSearch: RegExp;
		fileRead: RegExp;
	};
}

type FlowCapabilitiesParseResult =
	| { patterns: FlowCapabilityPatterns; errors: [] }
	| { patterns: null; errors: string[] };

const MAX_ENTRIES = 512;
const MAX_STRING = 1024;
/** Stateless flags only: `g` and `y` would make `test()` depend on the previous call. */
const ALLOWED_FLAGS = /^[imsu]*$/;

class Reader {
	readonly errors: string[] = [];

	record(value: unknown, where: string): Record<string, unknown> {
		if (value && typeof value === "object" && !Array.isArray(value)) {
			return value as Record<string, unknown>;
		}
		this.errors.push(`${where} must be a mapping`);
		return {};
	}

	string(value: unknown, where: string): string {
		if (typeof value === "string" && value.length > 0 && value.length <= MAX_STRING) return value;
		this.errors.push(`${where} must be a non-empty string of at most ${MAX_STRING} characters`);
		return "";
	}

	list(value: unknown, where: string): unknown[] {
		if (Array.isArray(value) && value.length > 0 && value.length <= MAX_ENTRIES) return value;
		this.errors.push(`${where} must be a non-empty list of at most ${MAX_ENTRIES} entries`);
		return [];
	}

	strings(value: unknown, where: string): string[] {
		return this.list(value, where).map((item, index) => this.string(item, `${where}[${index}]`));
	}

	regex(source: unknown, flags: unknown, where: string): RegExp {
		const text = this.string(source, `${where}.pattern`);
		const flagText = flags === undefined ? "" : flags;
		if (typeof flagText !== "string" || !ALLOWED_FLAGS.test(flagText)) {
			this.errors.push(`${where}.flags must use only i, m, s and u`);
			return /(?!)/;
		}
		try {
			return new RegExp(text, flagText);
		} catch {
			this.errors.push(`${where}.pattern is not a valid regular expression`);
			return /(?!)/;
		}
	}

	patternEntry(value: unknown, where: string): RegExp {
		const entry = this.record(value, where);
		return this.regex(entry.pattern, entry.flags, where);
	}

	oneOf<T extends string>(value: unknown, allowed: readonly T[], where: string): T {
		if (typeof value === "string" && (allowed as readonly string[]).includes(value)) {
			return value as T;
		}
		this.errors.push(`${where} must be one of ${allowed.join(", ")}`);
		return allowed[0] as T;
	}

	boolean(value: unknown, where: string): boolean {
		if (typeof value === "boolean") return value;
		this.errors.push(`${where} must be true or false`);
		return false;
	}
}

/** Validate parsed capability data. Any error rejects the whole file. */
function parseFlowCapabilities(raw: unknown): FlowCapabilitiesParseResult {
	const read = new Reader();
	const root = read.record(raw, "capability file");
	if (root.schema_version !== 1) read.errors.push("schema_version must be 1");

	const sensitivePaths = read.list(root.sensitive_paths, "sensitive_paths").map((value, index) => {
		const where = `sensitive_paths[${index}]`;
		const entry = read.record(value, where);
		return {
			pattern: read.regex(entry.pattern, entry.flags, where),
			label: read.string(entry.label, `${where}.label`),
			kind: read.oneOf(entry.kind, ["sensitive_file", "database_dump"] as const, `${where}.kind`),
			secret: read.boolean(entry.secret, `${where}.secret`),
		};
	});
	const credentialCommands = read
		.list(root.credential_commands, "credential_commands")
		.map((value, index) => {
			const where = `credential_commands[${index}]`;
			const entry = read.record(value, where);
			return {
				pattern: read.regex(entry.pattern, entry.flags, where),
				label: read.string(entry.label, `${where}.label`),
				kind: read.oneOf(
					entry.kind,
					["credential_command", "database_dump"] as const,
					`${where}.kind`,
				),
			};
		});
	const destructiveCommands = read
		.list(root.destructive_commands, "destructive_commands")
		.map((value, index) => {
			const where = `destructive_commands[${index}]`;
			const entry = read.record(value, where);
			return {
				pattern: read.regex(entry.pattern, entry.flags, where),
				label: read.string(entry.label, `${where}.label`),
			};
		});
	const broadDeletePatterns = read
		.strings(root.broad_delete_patterns, "broad_delete_patterns")
		.map((source, index) => read.regex(source, undefined, `broad_delete_patterns[${index}]`));
	const executables = read.record(root.executables, "executables");
	const executableSet = (key: string) =>
		new Set(read.strings(executables[key], `executables.${key}`).map((name) => name.toLowerCase()));
	const toolNames = read.record(root.tool_names, "tool_names");

	const patterns: FlowCapabilityPatterns = {
		trustedDomains: read.strings(root.trusted_domains, "trusted_domains"),
		exfilSinks: read.strings(root.exfil_sinks, "exfil_sinks"),
		sensitivePaths,
		credentialCommands,
		destructiveCommands,
		broadDeleteTargets: new Set(read.strings(root.broad_delete_targets, "broad_delete_targets")),
		broadDeletePatterns,
		commandPrefixes: new Set(read.strings(root.command_prefixes, "command_prefixes")),
		executables: {
			httpClients: executableSet("http_clients"),
			rawSocketClients: executableSet("raw_socket_clients"),
			copyClients: executableSet("copy_clients"),
			mailClients: executableSet("mail_clients"),
			dnsClients: executableSet("dns_clients"),
			interpreters: executableSet("interpreters"),
			shells: executableSet("shells"),
		},
		interpreterNetworkApi: read.patternEntry(root.interpreter_network_api, "interpreter_network_api"),
		interpreterPayloadHint: read.patternEntry(
			root.interpreter_payload_hint,
			"interpreter_payload_hint",
		),
		toolNames: {
			send: read.patternEntry(toolNames.send, "tool_names.send"),
			webRead: read.patternEntry(toolNames.web_read, "tool_names.web_read"),
			webSearch: read.patternEntry(toolNames.web_search, "tool_names.web_search"),
			fileRead: read.patternEntry(toolNames.file_read, "tool_names.file_read"),
		},
	};
	if (read.errors.length > 0) return { patterns: null, errors: read.errors };
	return { patterns, errors: [] };
}

/** Parse capability YAML text. */
export function parseFlowCapabilitiesYaml(text: string): FlowCapabilitiesParseResult {
	let raw: unknown;
	try {
		raw = parseYaml(text);
	} catch (error) {
		return { patterns: null, errors: [`invalid YAML: ${String(error)}`] };
	}
	return parseFlowCapabilities(raw);
}

function parseEmbedded(): FlowCapabilityPatterns {
	const { patterns, errors } = parseFlowCapabilitiesYaml(EMBEDDED_FLOW_CAPABILITIES_YAML);
	if (!patterns) {
		// Unreachable for a released build: the drift and schema tests parse this copy.
		throw new Error(`Embedded toxic-flow capability data is invalid: ${errors.join("; ")}`);
	}
	return patterns;
}

/** The shipped capability patterns (the embedded copy of `threats/flow/capabilities.yaml`). */
export const DEFAULT_FLOW_CAPABILITIES: FlowCapabilityPatterns = parseEmbedded();

interface CacheEntry {
	mtimeMs: number;
	size: number;
	patterns: FlowCapabilityPatterns;
}

const MAX_CACHED_FILES = 16;
const cache = new Map<string, CacheEntry>();

/**
 * Capability patterns for a threats directory: `<threatsDir>/flow/capabilities.yaml`
 * when it exists and validates, otherwise the embedded defaults. Never throws;
 * an unreadable or invalid file is logged. Parsed files are cached by path,
 * modification time and size, so an unchanged file costs one `stat` per call.
 */
export async function loadFlowCapabilities(
	threatsDir: string | undefined,
	logger: Logger = nullLogger,
): Promise<FlowCapabilityPatterns> {
	if (!threatsDir) return DEFAULT_FLOW_CAPABILITIES;
	const path = join(threatsDir, FLOW_CAPABILITIES_RELATIVE_PATH);
	try {
		const info = await stat(path);
		const cached = cache.get(path);
		if (cached && cached.mtimeMs === info.mtimeMs && cached.size === info.size) {
			return cached.patterns;
		}
		const text = await getFileContent(path);
		let patterns: FlowCapabilityPatterns;
		if (text === EMBEDDED_FLOW_CAPABILITIES_YAML) {
			patterns = DEFAULT_FLOW_CAPABILITIES;
		} else {
			const parsed = parseFlowCapabilitiesYaml(text);
			if (!parsed.patterns) {
				logger.warn(
					"Toxic-flow capability file is invalid; the embedded capability patterns are used instead",
					{ path, errors: parsed.errors.slice(0, 20) },
				);
				return DEFAULT_FLOW_CAPABILITIES;
			}
			patterns = parsed.patterns;
		}
		if (cache.size >= MAX_CACHED_FILES) cache.clear();
		cache.set(path, { mtimeMs: info.mtimeMs, size: info.size, patterns });
		return patterns;
	} catch (error) {
		if ((error as NodeJS.ErrnoException).code !== "ENOENT") {
			logger.warn(
				"Toxic-flow capability file is unreadable; the embedded capability patterns are used instead",
				{ path, error: error instanceof Error ? error.name : typeof error },
			);
		}
		return DEFAULT_FLOW_CAPABILITIES;
	}
}
